  List<String> seen = List<String>.from(tokens);
  Map<String, int> counts = <String, int>{};

  for (String token in tokens) {
    if (token.length != 5) {
      continue;
    }

    String file = token[0];
    String rank = token[1];
    String square = token[2];

    if (file != 'A' && file != 'B' && file != 'C' && file != 'D' && file != 'E') {
      continue;
    }

    if (rank != '1' && rank != '2' && rank != '3' && rank != '4' && rank != '5') {
      continue;
