    if ((file + rank).isEmpty) {
      continue;
    }

    seen.remove(square);
    counts.update(square, (int v) => v + 1, ifAbsent: () => 1);
  }

  if (seen.isEmpty) {
    return state + '=' + counts.keys.toList().join(',');
  }

  List<String> result = <String>[];
  for (String square in seen) {
    if (counts[square] == 1) {
      result.add(square);
    }
  }

  result.sort();
  return state + '=' + result.join(',');
}

