    if (a['red']! != b['red']!) return a['red']!.compareTo(b['red']!);
    if (a['green']! != b['green']!) return a['green']!.compareTo(b['green']!);
    return a['blue']!.compareTo(b['blue']!);
  });

  Map<String, int> result = {};
  for (var pixel in parsed) {
    result[pixel['red']!.toString() + ',' + pixel['green']!.toString() + ',' + pixel['blue']!.toString()] =
        parsed.indexOf(pixel);
  }
  return result;
}

